  catalogue(){this.dialog('Product catalogue',`<div class="toolbar">${btn('+ Add product','new-product','','button-green')}${btn('Buyer prices','buyer-prices')}${btn('Tax rules','tax-rules')}${this.state.profile.stockEnabled?btn('Stock balances','stock'):''}</div>${table(['Product / SKU','HSN','Price ₹','GST %','Verification','Actions'],this.state.products.map(p=>`<tr>${td((p.favourite?'★ ':'')+p.name+' / '+p.sku,'wrap')}${td(p.hsn)}${td(p.price,'num')}${td(p.gstRate===''?'Not set':p.gstRate,'num')}${td(p.verified?'Verified':'Unverified') }<td>${btn('Edit','edit-product',`data-id="${E(p.id)}"`)}</td></tr>`))}`,'catalogue');}
  productForm(record){const p=record||{id:crypto.randomUUID(),revision:0,name:'',sku:'',hsn:'',unit:'NOS',price:'',gstRate:'',taxability:'taxable',casePack:'1',cost:'0',cessRate:'0',category:'',active:true,verified:false,stockEnabled:false,openingStock:'0'};this.editingEntity=p;const f=(label,key,opts={})=>field(label,key,p[key]??'',{named:true,...opts});this.dialog(p.revision?'Edit product':'Add product',`<form id="product-form"><div class="field-grid">${f('Product name','name',{full:true})}${f('SKU','sku')}${f('Category','category')}${f('Full HSN / SAC (Text)','hsn')}${f('Unit','unit')}${f('Selling price (₹)','price',{type:'number'})}${f('Cost before tax (₹)','cost',{type:'number'})}${f('GST rate (%)','gstRate',{type:'number'})}${f('Tax category','taxability',{choices:[['taxable','Taxable'],['nil','Nil-rated'],['exempt','Exempt'],['nonGST','Non-GST']]})}${f('Cess rate (%)','cessRate',{type:'number'})}${f('Units per case','casePack',{type:'number'})}${check('Price includes tax','inclusive',p.inclusive,true)}${check('Favourite product','favourite',p.favourite,true)}${check('Active product','active',p.active!==false,true)}${check('Batch fields apply','batchEnabled',p.batchEnabled,true)}${f('Licence reference','licence')}${check('Track stock for this product','stockEnabled',p.stockEnabled,true)}${f('Opening stock (units)','openingStock',{type:'number'})}${f('Evidence / notification source','source',{full:true})}${f('Verified by','verifiedBy')}${f('Verification date','verifiedDate',{type:'date'})}${check('I reviewed this classification and rate','verified',p.verified,true)}</div><p class="help">Verification belongs to this catalogue version. Issued documents retain their original line snapshots.</p><div class="dialog-actions"><button class="button-green" type="submit">Save product</button></div></form>`,'product',true);}
  customers(){this.dialog('Customer directory',`<div class="toolbar">${btn('+ Add customer','new-customer','','button-green')}${btn('Buyer prices','buyer-prices')}</div>${table(['Customer','GSTIN','Terms','Phone','Actions'],this.state.parties.map(p=>`<tr>${td((p.favourite?'★ ':'')+p.name,'wrap')}${td(p.gstin||'Unregistered')}${td(p.paymentTerms)}${td(p.phone)}<td>${btn('Edit','edit-customer',`data-id="${E(p.id)}"`)}</td></tr>`))}`,'customers');}
  customerForm(record){const p=record||{id:crypto.randomUUID(),revision:0,name:'',gstin:'',stateCode:'27',billingAddress:'',shippingAddress:'',phone:'',email:'',paymentTerms:'Net 15 Days',favourite:false};const existing=this.state.parties.find(x=>x.id===p.id);if(existing)p.revision=existing.revision;this.editingEntity=p;const f=(label,key,opts={})=>field(label,key,p[key]??'',{named:true,...opts});this.dialog(p.revision?'Edit customer':'Add customer',`<form id="customer-form"><div class="field-grid">${f('Customer name','name',{full:true})}${f('GSTIN (optional)','gstin')}${f('State','stateCode',{choices:Object.entries(C.STATES)})}${f('Billing address','billingAddress',{type:'textarea',full:true})}${f('Shipping address','shippingAddress',{type:'textarea',full:true})}${f('Phone with country code','phone')}${f('Email','email')}${f('Payment terms','paymentTerms',{full:true})}${check('Favourite buyer','favourite',p.favourite,true)}</div><div class="dialog-actions"><button class="button-green" type="submit">Save customer</button></div></form>`,'customer',true);}
  taxRules(){this.dialog('Tax rules & evidence',`<div class="toolbar">${btn('+ Add reviewed rule','new-tax','','button-green')}</div><p class="help">No statutory rate table is pre-confirmed. Effective dates alone do not resolve supply/payment transition exceptions. Importing a rule never verifies it.</p>${table(['HSN','Product','Rate %','Effective from / to','Status','Evidence','Actions'],this.state.taxRules.map(r=>`<tr>${td(r.hsn)}${td(this.state.products.find(p=>p.id===r.productId)?.name||'All matching HSN','wrap')}${td(r.rate)}${td(r.effectiveFrom+' / '+(r.effectiveTo||'Open'))}${td(r.verified?'Verified':'Review needed')}${td(r.source,'wrap')}<td>${btn('Edit / verify','edit-tax',`data-id="${E(r.id)}"`)}</td></tr>`))}`,'taxRules');}
  taxForm(record){const r=record||{id:crypto.randomUUID(),revision:0,productId:'',hsn:'',rate:'',effectiveFrom:C.dateToday(),effectiveTo:'',source:'',verified:false,verifiedBy:'',verifiedDate:''};this.editingEntity=r;const f=(label,key,opts={})=>field(label,key,r[key]??'',{named:true,...opts});this.dialog('Tax rule review',`<form id="tax-form"><div class="field-grid">${f('Product (optional; otherwise HSN match)','productId',{choices:this.state.products.map(p=>[p.id,p.name]),full:true})}${f('HSN / SAC','hsn')}${f('GST rate (%)','rate',{type:'number'})}${f('Effective from','effectiveFrom',{type:'date'})}${f('Effective to (optional)','effectiveTo',{type:'date'})}${f('Official source URL (HTTPS)','source',{full:true})}${f('Verified by','verifiedBy')}${f('Verified date','verifiedDate',{type:'date'})}${check('I reviewed applicability, dates and exceptions','verified',r.verified,true)}</div><div class="dialog-actions"><button class="button-green" type="submit">Save rule</button></div></form>`,'tax',true);}
